// Configuration du workflow « Qualification ».
// C'est le seul nœud à modifier après l'import : renseigne les ID des listes
// Brevo affichés par scripts/setup_brevo.py.
const config = {
  marque: 'Pacewell',
  modele: 'claude-haiku-5-5',
  // Tarifs Claude Haiku 5.5 (USD par million de tokens, prompts < 100k tokens).
  // Source : platform.claude.com/docs/en/about-claude/pricing — à revérifier de temps en temps.
  prixEntreeParMillion: 0.10,
  prixSortieParMillion: 0.50,
  seuilLeadChaud: 70,
  emailAlerte: 'simondelruepro@gmail.com',
  expediteur: { email: 'audit@simondelrue.fr', name: 'Pacewell CRM' },
  delaiDoublonJours: 7,
  // Adresses des API (modifiables pour les tests).
  urlBrevo: 'https://api.brevo.com/v3',
  urlClaude: 'https://api.anthropic.com/v1',
  listes: {
    ROUTE_DEBUTANT: 0,
    ROUTE_PERF: 0,
    TRAIL_DECOUVERTE: 0,
    TRAIL_ENDURANCE: 0,
    A_QUALIFIER: 0,
  },
};

// Le webhook range le formulaire dans `body`.
return { formulaire: $json.body ?? {}, config };

// Nettoie et valide les réponses du formulaire.
// Sortie : { ok, erreur?, lead? }. Un lead invalide ne va jamais jusqu'à l'IA ni à Brevo.
const CHOIX = {
  pratique: ['route', 'trail', 'les-deux'],
  frequence: ['moins-1', '1-2', '3-4', '5-plus'],
  objectif: ['forme', '10km', 'semi', 'marathon', 'trail-court', 'ultra'],
  budget: ['moins-150', '150-400', '400-plus'],
};
const f = $json.formulaire || {};
const texte = (v, max) => String(v ?? '').trim().replace(/\s+/g, ' ').slice(0, max);

if (texte(f.site_web, 200)) {
  return { ok: false, erreur: 'spam' }; // champ piège rempli : un robot
}

const lead = {
  email: texte(f.email, 200).toLowerCase(),
  prenom: texte(f.prenom, 60).replace(/[<>]/g, ''),
  pratique: texte(f.pratique, 20),
  frequence: texte(f.frequence, 20),
  objectif: texte(f.objectif, 20),
  budget: texte(f.budget, 20),
  consentement: f.consentement === true || f.consentement === 'oui' || f.consentement === 'on',
};

if (!/^[^@\s]+@[^@\s]+\.[^@\s]{2,}$/.test(lead.email)) {
  return { ok: false, erreur: 'Adresse email invalide.' };
}
if (!lead.consentement) {
  return { ok: false, erreur: 'Le consentement est obligatoire pour recevoir nos emails.' };
}
for (const [champ, valeurs] of Object.entries(CHOIX)) {
  if (!valeurs.includes(lead[champ])) {
    return { ok: false, erreur: `Réponse invalide pour « ${champ} ».` };
  }
}
return { ok: true, lead };

// Dédoublonnage. Entrée : la réponse brute de Brevo (GET /contacts/{email}).
// - Nouveau contact (404) : on qualifie.
// - Contact déjà qualifié avec les mêmes réponses il y a moins de N jours :
//   on ne rappelle pas l'IA (économie de coût), on réutilise sa qualification.
// - Sinon (réponses changées ou qualification ancienne) : on requalifie.
const { lead } = $('Nettoyer et valider').item.json;
const { config } = $('Configuration').item.json;
const statut = $json.statusCode;
const contact = statut === 200 ? ($json.body || {}) : null;
const a = (contact && contact.attributes) || {};

const memesReponses = contact
  && a.PRATIQUE === lead.pratique && a.FREQUENCE === lead.frequence
  && a.OBJECTIF === lead.objectif && a.BUDGET === lead.budget;
const qualifieLe = a.QUALIFIE_LE ? new Date(a.QUALIFIE_LE) : null;
const recent = qualifieLe && (Date.now() - qualifieLe.getTime()) < config.delaiDoublonJours * 86400000;

if (memesReponses && recent && a.SEGMENT && a.SEGMENT !== 'A_QUALIFIER') {
  return {
    lead,
    doublon: true,
    existant: true,
    qualification: {
      segment: a.SEGMENT, niveau: a.NIVEAU, score: Number(a.SCORE) || 0,
      raison: a.RAISON_IA || '', source: 'doublon', cout_usd: 0,
    },
  };
}
return { lead, doublon: false, existant: Boolean(contact) };

// Prépare la requête envoyée à Claude.
// Minimisation des données (RGPD) : l'IA ne reçoit NI l'email NI le prénom,
// seulement les réponses au questionnaire.
const { lead } = $json;
const { config } = $('Configuration').item.json;

const consignes = `Tu es l'outil de qualification CRM de ${config.marque}, une boutique en ligne de running et de trail.
À partir des réponses d'un nouvel inscrit, tu le classes pour personnaliser ses emails.

Segments possibles (choisis-en exactement un) :
- ROUTE_DEBUTANT : court sur route, débute ou reprend, objectif forme ou 10 km, 2 sorties par semaine maximum.
- ROUTE_PERF : court sur route avec un objectif chronométré (semi, marathon) ou 3 sorties et plus par semaine.
- TRAIL_DECOUVERTE : découvre le trail, objectif forme ou trail court, pratique occasionnelle à régulière.
- TRAIL_ENDURANCE : trail engagé, objectif ultra, ou trail avec 3 sorties et plus par semaine.
Règles : « route » donne toujours un segment ROUTE_*, « trail » toujours un segment TRAIL_*.
Pour « les-deux », l'objectif tranche (trail-court ou ultra : TRAIL_* ; sinon ROUTE_*).

Niveau : debutant, intermediaire ou confirme.
Score de 1 à 100 : potentiel commercial sur un an (fréquence de pratique, budget annuel, ambition de l'objectif).
Repères : moins d'une sortie et budget faible, autour de 15 ; pratique régulière et budget moyen, autour de 50 ;
pratique intensive, budget élevé et objectif ambitieux, au-delà de 80.

Réponds UNIQUEMENT avec un objet JSON, sans texte autour :
{"segment": "...", "niveau": "...", "score": 0, "raison": "une phrase de 25 mots maximum"}`;

const reponses = {
  pratique: lead.pratique,
  sorties_par_semaine: lead.frequence,
  objectif: lead.objectif,
  budget_annuel_equipement_euros: lead.budget,
};

return {
  requete: {
    model: config.modele,
    max_tokens: 300,
    system: consignes,
    messages: [{ role: 'user', content: 'Réponses du formulaire :\n' + JSON.stringify(reponses, null, 1) }],
  },
};

// Valide la réponse de Claude. Garde-fou principal du workflow :
// toute réponse absente, illisible ou incohérente envoie le contact
// dans le segment par défaut A_QUALIFIER, avec la raison du repli.
const SEGMENTS = ['ROUTE_DEBUTANT', 'ROUTE_PERF', 'TRAIL_DECOUVERTE', 'TRAIL_ENDURANCE'];
const NIVEAUX = ['debutant', 'intermediaire', 'confirme'];
const { lead } = $('Dédoublonner').item.json;
const { config } = $('Configuration').item.json;

const repli = (motif, cout = 0) => ({
  lead,
  qualification: {
    segment: 'A_QUALIFIER', niveau: '', score: 0,
    raison: `Qualification automatique impossible (${motif}).`,
    source: 'repli', cout_usd: cout,
  },
});

const statut = $json.statusCode;
const corps = $json.body || {};
const usage = corps.usage || {};
const cout = ((usage.input_tokens || 0) * config.prixEntreeParMillion
  + (usage.output_tokens || 0) * config.prixSortieParMillion) / 1e6;

if (statut !== 200) {
  return repli(`API ${statut || 'injoignable'}`, 0);
}

const texte = (corps.content || []).filter((b) => b.type === 'text').map((b) => b.text).join('');
let r;
try {
  const debut = texte.indexOf('{');
  const fin = texte.lastIndexOf('}');
  r = JSON.parse(texte.slice(debut, fin + 1));
} catch (e) {
  return repli('JSON illisible', cout);
}

const score = Number(r.score);
if (!SEGMENTS.includes(r.segment)) return repli('segment inconnu', cout);
if (!NIVEAUX.includes(r.niveau)) return repli('niveau inconnu', cout);
if (!Number.isInteger(score) || score < 1 || score > 100) return repli('score hors bornes', cout);
if (typeof r.raison !== 'string' || !r.raison.trim()) return repli('raison absente', cout);
// Cohérence avec les réponses : l'IA ne peut pas classer un coureur sur route dans le trail.
if (lead.pratique === 'route' && !r.segment.startsWith('ROUTE')) return repli('segment incohérent', cout);
if (lead.pratique === 'trail' && !r.segment.startsWith('TRAIL')) return repli('segment incohérent', cout);

return {
  lead,
  qualification: {
    segment: r.segment, niveau: r.niveau, score,
    raison: r.raison.trim().slice(0, 250),
    source: 'ia', cout_usd: Math.round(cout * 1e6) / 1e6,
  },
};

// Prépare la création ou la mise à jour du contact dans Brevo (upsert).
// Le contact est ajouté à la liste de son segment et retiré des autres,
// pour qu'un changement de profil ne le laisse pas dans deux parcours.
const { lead, qualification: q } = $json;
const { config } = $('Configuration').item.json;
const idListe = config.listes[q.segment];
const autres = Object.values(config.listes).filter((id) => id && id !== idListe);

return {
  lead,
  qualification: q,
  contact: {
    email: lead.email,
    updateEnabled: true,
    attributes: {
      PRENOM: lead.prenom,
      PRATIQUE: lead.pratique,
      FREQUENCE: lead.frequence,
      OBJECTIF: lead.objectif,
      BUDGET: lead.budget,
      SEGMENT: q.segment,
      NIVEAU: q.niveau,
      SCORE: q.score,
      RAISON_IA: q.raison,
      SOURCE_QUALIF: q.source,
      COUT_IA_USD: q.cout_usd,
      QUALIFIE_LE: new Date().toISOString().slice(0, 10),
    },
    listIds: idListe ? [idListe] : [],
    unlinkListIds: autres,
  },
  leadChaud: q.score >= config.seuilLeadChaud,
};

// Email d'alerte « lead chaud », envoyé via l'API transactionnelle Brevo.
const { lead, qualification: q } = $('Préparer Brevo').item.json;
const { config } = $('Configuration').item.json;
const e = (s) => String(s ?? '').replace(/[&<>"']/g, (c) => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;', "'": '&#39;' }[c]));

const lignes = [
  ['Prénom', lead.prenom], ['Email', lead.email], ['Segment', q.segment], ['Niveau', q.niveau],
  ['Score', `${q.score}/100`], ['Pourquoi', q.raison], ['Pratique', lead.pratique],
  ['Sorties/semaine', lead.frequence], ['Objectif', lead.objectif], ['Budget annuel', lead.budget],
].map(([k, v]) => `<tr><td style="padding:6px 14px 6px 0;color:#6e6e73">${e(k)}</td><td style="padding:6px 0">${e(v)}</td></tr>`).join('');

return {
  email: {
    sender: config.expediteur,
    to: [{ email: config.emailAlerte }],
    replyTo: { email: lead.email },
    subject: `🔥 Lead chaud ${config.marque} : ${lead.prenom || lead.email} (${q.score}/100)`,
    htmlContent: `<div style="font-family:-apple-system,Helvetica,Arial,sans-serif;color:#1d1d1f">
<h2 style="margin:0 0 12px">Nouveau lead chaud : ${q.score}/100</h2>
<table style="font-size:15px;border-collapse:collapse">${lignes}</table>
<p style="color:#6e6e73;font-size:13px">Répondre à cet email écrit directement au lead.</p></div>`,
    tags: ['pacewell-alerte'],
  },
};
